code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    if (n == 0) {
        cout << 1 << endl;
    } else {
        int count = 0;
        while (n > 0) {
            n = n / 10;
            count++;
        }
        cout << count << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        if (n == 0) {
            System.out.println(1);
        } else {
            int count = 0;
            while (n > 0) {
                n = n / 10;
                count++;
            }
            System.out.println(count);
        }
    }
}
